B.ayh=s(["\u042f\u043d\u0432","\u0424\u0435\u0432","\u041c\u0430\u0440","\u0410\u043f\u0440","\u041c\u0430\u0439","\u0418\u044e\u043d","\u0418\u044e\u043b","\u0410\u0432\u0433","\u0421\u0435\u043d","\u041e\u043a\u0442","\u041d\u043e\u044f","\u0414\u0435\u043a"],t.s)
B.b_K=new A.bA("Sahih al-Bukhari","Imam Muhammad al-Bukhari (d. 870 CE)","Widely considered the most authentic book after the Qur\u2019an.")
B.b_F=new A.bA("Sahih Muslim","Imam Muslim ibn al-Hajjaj (d. 875 CE)","Nearly equal to Sahih al-Bukhari in authenticity.")
B.b_5=new A.bA("Sunan Abu Dawood","Abu Dawood al-Sijistani (d. 889 CE)","Primarily focuses on rulings of Islamic law (fiqh).")
B.b_v=new A.bA("Jami\u2019 al-Tirmidhi","Imam al-Tirmidhi (d. 892 CE)","Notable for detailed classifications of hadith and notes on the different legal schools.")
B.b_4=new A.bA("Sunan an-Nasa\u2019i","Al-Nasa\u2019i (d. 915 CE)","Highly respected for the strict criteria the author used in selecting narrators.")
B.b_S=new A.bA("Sunan Ibn Majah","Ibn Majah (d. 887 CE)","Added as the sixth book by the scholar Ibn al-Qaisarani in the 11th century \u2014 completing the six canonical collections (al-Kutub as-Sittah).")
B.ayi=s([B.b_K,B.b_F,B.b_5,B.b_v,B.b_4,B.b_S],t.iT)
